// Ruta de una tutoría previa al parcial. Semanas 8–11 de las guías del docente:
// validación, Mientras, Repetir y Para.
//
// Cada lección sigue el mismo orden: idea → ejemplo → traza (tabla) → error típico.
// Los ejercicios van de predecir (choice/typed), a ordenar (reorder), a escribir código
// (code), que se ejecuta y se califica en la plataforma. `theory` en un ejercicio
// code son los índices de los bloques de teoría que abre «Ver el tema».
const code = (...rows) => rows.join('\n')

// Bloques de teoría: `syntax` muestra la plantilla de una estructura con sus partes;
// `tryIt` es un ejemplo completo que se ejecuta en la lección.
const syntax = (title, template, parts) => ({ type: 'syntax', title, template, parts })
const tryIt = (ask, source, datos) => ({ type: 'try', ask, code: source, ...(datos ? { datos } : {}) })

